def timer(func):
    import time
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f'{func.__name__} 执行时间: {end-start:.4f}秒')
        return result
    return wrapper

@timer
def slow_function():
    import time
    time.sleep(1)
    print('函数执行完成')

slow_function()

def log_decorator(func):
    def wrapper(*args, **kwargs):
        print(f'调用 {func.__name__}')
        result = func(*args, **kwargs)
        print(f'{func.__name__} 返回 {result}')
        return result
    return wrapper

@log_decorator
def add(a, b):
    return a + b

result = add(2, 3)

def require_admin(func):
    def wrapper(user, *args, **kwargs):
        if user.get('role') != 'admin':
            print('权限不足')
            return None
        return func(user, *args, **kwargs)
    return wrapper

@require_admin
def delete_user(user, user_id):
    print(f'删除用户 {user_id}')
    return True

admin = {'name': 'Alice', 'role': 'admin'}
user = {'name': 'Bob', 'role': 'user'}

delete_user(admin, 123)
delete_user(user, 456)

def countdown(n):
    while n > 0:
        yield n
        n -= 1

for num in countdown(5):
    print(num)

def fibonacci():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

fib = fibonacci()
for _ in range(10):
    print(next(fib), end=' ')

def read_lines(filename):
    with open(filename, 'r') as f:
        for line in f:
            yield line.strip()

# 使用示例
for line in read_lines('data.txt'):
    if line:  # 跳过空行
        print(f'处理: {line}')
